using UnityEngine;using UnityEditor;using System;using System.IO;
public static class ValidateMowerCoast {
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");GameObject floor=null,copy=null,wall=null;var mode=Physics.simulationMode;int checks=0;void Check(bool v,string msg){if(!v)throw new Exception(msg);checks++;}
 try{Physics.simulationMode=SimulationMode.Script;floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(200,1,200);copy=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/Lawnmower/Driveable/Lawnmower_With_Trailer.prefab"),new Vector3(10000,.02f,10000),Quaternion.identity);var lawn=copy.GetComponentInChildren<LawnmowerController>();var engine=lawn.GetComponent<MotorollerController>();var rig=engine.Movement;var body=lawn.trailerJoint.GetComponent<Rigidbody>();Physics.SyncTransforms();
 void Step(float throttle,float turn,bool brake){engine.Drive(throttle,turn,brake,.02f);lawn.UpdateHitch();Physics.Simulate(.02f);lawn.SendMessage("LateUpdate");}
 for(int i=0;i<250;i++)Step(0,0,true);Check(lawn.trailerWheels[0].isGrounded&&lawn.trailerWheels[1].isGrounded,"Trailer wheels supported; position="+body.position+" rotation="+body.rotation.eulerAngles+" wheel0="+lawn.trailerWheels[0].transform.position+" grounded0="+lawn.trailerWheels[0].isGrounded+" grounded1="+lawn.trailerWheels[1].isGrounded);rig.SetRidden(true);var start=lawn.transform.position;var trailerStart=body.position;
 for(int i=0;i<350;i++)Step(1,0,false);Check(lawn.transform.position.z>start.z+15,"Mower moves forward "+lawn.transform.position+" speed="+rig.Speed);Check(body.position.z>trailerStart.z+15,"Trailer follows");Check(Vector3.Distance(lawn.hitchTarget.position,body.transform.TransformPoint(lawn.trailerJoint.anchor))<.15f,"Hitch stays connected");Check(rig.Speed>4.5f,"Full engine speed");var coastStart=lawn.transform.position;rig.SetRidden(false);Check(rig.IsCoasting,"Mower coasts after exit");for(int k=0;k<60;k++){rig.TickUnoccupied(.02f);lawn.UpdateHitch();Physics.Simulate(.02f);lawn.SendMessage("LateUpdate");}Check(Vector3.Distance(coastStart,lawn.transform.position)>.5f&&!rig.IsCoasting,"Mower rolls then stops");Check(Vector3.Distance(lawn.hitchTarget.position,body.transform.TransformPoint(lawn.trailerJoint.anchor))<.2f,"Trailer follows coast");rig.SetRidden(true);
 for(int i=0;i<100;i++)Step(0,0,true); wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=new Vector3(body.position.x,1,body.position.z-5.5f);wall.transform.localScale=new Vector3(15,2,.2f);Physics.SyncTransforms();for(int i=0;i<300;i++)Step(-1,0,false);Check(body.position.z-4.5f>wall.transform.position.z,"Trailer cannot reverse through wall: body="+body.position+" wall="+wall.transform.position);Check(Vector3.Distance(lawn.hitchTarget.position,body.transform.TransformPoint(lawn.trailerJoint.anchor))<.6f,"Blocked trailer hitch stays close");UnityEngine.Object.DestroyImmediate(wall); for(int i=0;i<150;i++)Step(1,.6f,false);float articulation=Quaternion.Angle(lawn.transform.rotation,body.rotation);Check(articulation>5&&articulation<75,"Trailer articulates "+articulation);Check(lawn.transform.position.y>-.1f&&body.position.y>-.3f,"Ground maintained");
 for(int i=0;i<250;i++)Step(0,0,true);Check(Mathf.Abs(rig.Speed)<.01f,"Brakes stop");start=lawn.transform.position;for(int i=0;i<100;i++)Step(-1,0,false);Check(Vector3.Distance(start,lawn.transform.position)>1,"Reverse with trailer");Check(Vector3.Distance(lawn.hitchTarget.position,body.transform.TransformPoint(lawn.trailerJoint.anchor))<.2f,"Reverse hitch stays connected");
 for(int i=0;i<100;i++)Step(0,0,true);rig.SetRidden(false);Check(!rig.IsRidden,"Parked");string result="PASS "+checks+" mower/trailer physics checks; turn articulation="+articulation;File.WriteAllText("output/Lawnmower/coast-validation.txt",result);return result;
 }finally{if(wall)UnityEngine.Object.DestroyImmediate(wall);if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);Physics.simulationMode=mode;}}
}



